(function(){'use strict';const cache=new Map();function strategy(id,lang){const u=new URL(lang==='en'?'index-en.html':'index-ar.html',location.href);u.searchParams.set('strategy',String(id));return u.href}function qr(url){if(cache.has(url))return cache.get(url);const holder=document.createElement('div');const q=new QRCode(holder,{text:url,correctLevel:QRCode.CorrectLevel.M});const m=q._oQRCode,n=m.getModuleCount(),c=document.createElement('canvas');c.width=c.height=(n+8)*6;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#123b3d';for(let r=0;r<n;r++)for(let col=0;col<n;col++)if(m.isDark(r,col))ctx.fillRect((col+4)*6,(r+4)*6,6,6);const png=c.toDataURL('image/png');cache.set(url,png);return png}window.BOUSALA_LINKS={strategy,qr};function gallery(){for(const card of document.querySelectorAll('.qr-card')){const a=card.querySelector('a'),img=card.querySelector('img'),id=new URL(a.href).searchParams.get('strategy');a.href=strategy(id,document.documentElement.lang);img.src=qr(a.href)}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',gallery);else gallery()})();
